<aside class="ff-revision-panel" x-show="revisionOpen" x-cloak aria-label="{{ __('filaforge::studio.builder.revisions') }}">
<div class="ff-panel-heading"><h2><span class="ff-heading-icon" x-html="iconSvg('clock-rotate-left')"></span>{{ __('filaforge::studio.builder.revisions') }}</h2><button type="button" class="ff-btn" x-on:click="revisionOpen=false"><span class="ff-button-icon" x-html="iconSvg('xmark')"></span>{{ __('filaforge::studio.builder.close') }}</button></div>
<p class="ff-muted">{{ __('filaforge::studio.builder.restore_help') }}</p>
<p x-show="!revisionItems.length" class="ff-muted">{{ __('filaforge::studio.builder.no_revisions') }}</p>
<template x-for="revision in revisionItems" :key="revision.id"><div class="ff-revision-row"><span x-text="@js(__('filaforge::studio.builder.version'))+' '+revision.version+' · '+new Date(revision.created_at).toLocaleString()"></span><button type="button" class="ff-btn" x-on:click="compareRevision(revision.id)"><span class="ff-button-icon" x-html="iconSvg('code-compare')"></span>{{ __('filaforge::studio.builder.compare') }}</button></div></template>
<template x-if="revisionCompare"><div><div class="ff-revision-diff"><div><h3>{{ __('filaforge::studio.builder.previous') }}</h3><pre dir="ltr" x-text="revisionCompare.before"></pre></div><div><h3>{{ __('filaforge::studio.builder.current') }}</h3><pre dir="ltr" x-text="revisionCompare.after"></pre></div></div><button type="button" class="ff-btn ff-primary" x-on:click="restoreRevision(revisionCompare.id)" :disabled="busy"><span class="ff-button-icon" x-html="iconSvg('rotate-left')"></span>{{ __('filaforge::studio.builder.restore') }}</button></div></template>
</aside>
